return (function execute({ input }) {
  return input.all().map((item, index) => ({
    json: { ...item.json, attempt: (item.json.attempt || 0) + 1 },
    pairedItem: { item: index },
  }));
})({ input: $input, now: $now, nodes: {  }, category: "nacionais" }, {  });

// Generated from src/n8n/readResponse. Edit the source, then run npm run build.

return (function execute({ input, nodes }) {
  return input.all().map((item, index) => {
    const context = nodes.attempt.itemMatching(index).json;
    const response = item.json;
    let html = "";
    if (typeof response.body === "string") {
      html = response.body;
    } else if (typeof response.data === "string") {
      html = response.data;
    }
    return {
      json: {
        ...context,
        statusCode: response.statusCode || 0,
        error: response.error ? "Falha HTTP" : null,
        data: html,
      },
      pairedItem: { item: index },
    };
  });
})({ input: $input, now: $now, nodes: { attempt: $("Tentativa nacionais") }, category: "nacionais" }, {  });

