      return failedPage(context, "HTML sem cards e sem confirmação de pesquisa vazia");
    }

    const warnings = [];
    if (expectedCount !== cards.length) {
      warnings.push(
        "Cobertura parcial: " + cards.length + " de " + expectedCount + " cards recebidos",
